nodes = [18,26,59,102,150,168,173,196,216,248,255,269]
start,end = 33039,45039
# build list of events in window
ev = [e for e in events if start<=e[2]<=end]
# index by pair
from collections import defaultdict
by_pair = defaultdict(list)
for u,v,t in ev:
    by_pair[(u,v)].append(t)
# For undirected interactions? The interactions are directed (u contacted v). Closure wave likely cares about pairs interacting regardless of direction. So build undirected pair times
by_undir = defaultdict(list)
for u,v,t in ev:
    a,b = (u,v) if u<=v else (v,u)
    by_undir[(a,b)].append((u,v,t))
# Find triples: a and b in target nodes; c any node; find times t_ac (any direction) and t_bc; then find t_ab after max(t_ac,t_bc) within 800
results = []
for a in nodes:
    for b in nodes:
        if a>=b: continue
        # find all interactions a-c and b-c with same c
        for (u,v,t) in ev:
            # consider if u==a or v==a
            pass
# Instead iterate over c
for c in set([e[0] for e in ev] + [e[1] for e in ev]):
    # get times when nodes in 'nodes' interacted with c
    times = defaultdict(list) # node -> list of times
    for u,v,t in ev:
        if v==c and u in nodes:
            times[u].append(t)
        if u==c and v in nodes:
            times[v].append(t)
    # for each pair a,b in nodes with times to c
    for i, a in enumerate(nodes):
        for b in nodes[i+1:]:
            for ta in times.get(a,[]):
                for tb in times.get(b,[]):
                    support_time = max(ta,tb)
                    # find any a-b interaction after support_time and within 800
                    for u,v,t in ev:
                        # undirected check
                        if (u==a and v==b) or (u==b and v==a):
                            if support_time < t <= support_time+800:
                                results.append({'a':a,'b':b,'c':c,'ta':ta,'tb':tb,'t_close':t,'support_time':support_time})
# print results
print('found',len(results),'closure candidates')
for r in results:
    print(r)

